"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[89],{89:(e,n,a)=>{a.d(n,{Av:()=>s,B7:()=>t,CT:()=>i,Ex:()=>c,I1:()=>l,R6:()=>r,le:()=>o});let i={name:"Jade Orchid Aesthetics",email:"rk@jadeorchidaesthetics.com",phone:"07951 718449",phoneIntl:"+44 7951 718449",hours:[["Monday – Friday","10:00 AM to 5:00 PM"],["Saturday","10:00 AM to 3:00 PM"],["Sunday","Closed"]]},t=[{area:"Leicester",name:"Whitehouse Dental Surgery",lines:["386 East Park Road","Leicester LE5 5HH"],img:"/img/loc-whitehouse.jpg",map:"https://www.google.com/maps/search/?api=1&query=386+East+Park+Road+Leicester+LE5+5HH"},{area:"Leicester",name:"Bright Smiles Dental Practice",lines:["86 Hinckley Road","Leicester LE3 0RD"],img:"/img/loc-brightsmiles.jpg",map:"https://www.google.com/maps/search/?api=1&query=86+Hinckley+Road+Leicester+LE3+0RD"},{area:"Wolverhampton",name:"AK Clinics",lines:["King's House Business Centre","St John's Square","Wolverhampton WV2 4DT"],img:"/img/loc-ak.jpg",map:"https://www.google.com/maps/search/?api=1&query=King%27s+House+Business+Centre+St+John%27s+Square+Wolverhampton+WV2+4DT"}],r=[{slug:"skin-consultations",title:"Skin Consultations",img:"/img/tile-consult.jpg",desc:"Advanced skin analysis and a personalised plan built around your concerns, skin condition and goals.",hover:"Advanced skin analysis to understand your concerns and create your personalised skin, treatment and homecare plan.",services:"Opatra DOME analysis, consultation, treatment planning, skincare and inside-out recommendations"},{slug:"skin-rejuvenation-facials",title:"Skin Rejuvenation & Facials",img:"/img/tile-rejuv.jpg",desc:"Advanced facials and skin-renewal treatments designed to improve texture, hydration, clarity and overall skin health.",hover:"Advanced facials, microneedling and skin-renewal treatments for pigmentation, acne, hydration, texture and healthy ageing.",services:"SkinPen microneedling, HydrO₂ facials, Fire & Ice Facial, Medik8 Age-Defying Facial, chemical peels and LED therapy"},{slug:"regenerative-aesthetics",title:"Regenerative Aesthetics",img:"/img/tile-regen.jpg",desc:"Treatments that use your body's own regenerative components to support repair, collagen and natural-looking rejuvenation.",hover:"PRP, PRF and regenerative treatments designed to support collagen, repair and natural-looking skin rejuvenation.",services:"PRP, PRF, iPRF and autologous collagen biofiller"},{slug:"facial-balancing-aesthetic-refinement",title:"Facial Balancing & Aesthetic Refinement",img:"/img/tile-balance.jpg",desc:"Personalised injectable treatments designed to soften, restore and rejuvenate while respecting your natural features.",hover:"Personalised aesthetic treatments to soften, restore facial balance and enhance your natural features.",services:"Anti-wrinkle treatments, dermal fillers, skin boosters and polynucleotides"},{slug:"laser-hair-removal",title:"Laser Hair Removal",img:"/img/tile-laser.jpg",desc:"Personalised laser hair-reduction programmes for the face and body, beginning with a consultation and test patch.",hover:"Advanced laser hair reduction for the face and body, with personalised treatment courses and a complimentary test patch.",services:"Face and body treatment areas, consultation, test patch and treatment courses"},{slug:"skin-health-wellness",title:"Skin Health & Wellness",img:"/img/tile-health.jpg",desc:"Inside-out skin health and gentle, specialist care for sensitive, compromised or cancer-treatment-affected skin.",hover:"Inside-out skin health and specialist support for sensitive, compromised and cancer-treatment-affected skin.",services:"Skin supplements, gut–skin support, Harmony Facial, oncology-conscious skin support and gentle wellness massage"}],s=[{slug:"discover-your-skin",cat:"skin-consultations",title:"Discover Your Skin",img:"/img/t-discover.jpg",desc:"Advanced skin analysis and clinical consultation to understand your skin and create a personalised plan.",topics:["OPATRA DOME analysis","Skin concerns","Lifestyle","Treatment planning","Professional skincare / homecare","Reviews and progress"],intro:["Healthy skin starts with understanding it. Every journey at Jade Orchid begins with a calm, unhurried consultation where advanced skin analysis, clinical expertise and genuine conversation come together.","Using the OPATRA DOME Skin Analysis System, we look beyond the surface to better understand your skin. Together, we create a personalised plan shaped around your concerns, lifestyle and long-term skin goals."],items:[{name:"Skin analysis & consultation",desc:"A detailed assessment of your skin, concerns, lifestyle and goals using the OPATRA DOME."},{name:"Treatment planning",desc:"A structured pathway of treatments, skincare and maintenance, sequenced for your skin."},{name:"Skin Passport",desc:"A personal record of your treatments, skincare recommendations and progress over time, so your skin journey can be tracked and refined as your skin improves."}],benefits:["Understand what your skin needs","A personalised plan, not a one-size-fits-all package","Professional skincare and homecare recommendations","Regular reviews to measure progress"]},{slug:"advanced-facials",cat:"skin-rejuvenation-facials",title:"Advanced Facials",img:"/img/t-facials.jpg",desc:"Professional facial treatments selected around your skin, concerns and individual goals.",topics:["HydrO₂ Facial","Fire & Ice Facial","Medik8 Crystal Retinal Age-Defying Facial","BioCell Trinity / Million Dollar Facial","LED where appropriate"],intro:["More than a facial — clinically guided skin treatments designed to deeply cleanse, hydrate, strengthen and restore healthier-looking skin.","Your facial is chosen around your skin, your concerns and your goals, and can be combined with LED therapy where appropriate."],items:[{name:"3D HydrO₂ Facial",desc:"Combines hydrodermabrasion, oxygen therapy and targeted serums to deeply cleanse, exfoliate and hydrate. Available as Express, Advanced and Ultimate levels."},{name:"Million Dollar Facial System",desc:"Combines dermaplaning, lymphatic drainage, microneedling and targeted serums to rejuvenate and stimulate collagen. Mini, Signature and Miracle Mask levels.",price:"Mini \xa375 \xb7 Signature \xa399"},{name:"Fire & Ice Facial",desc:"A results-driven facial pairing warming and cooling stages to refresh and brighten the skin."},{name:"Medik8 Crystal Retinal Age-Defying Facial",desc:"A professional facial built around Medik8 Crystal Retinal to support healthy ageing."},{name:"Chemical peels",desc:"Medik8 Universal AHA (\xa390), Clarity (\xa395) and Retinol (\xa3105) peels to improve tone, clarity and texture."},{name:"Sea Algae Peel",desc:"A natural resurfacing treatment often described as organic microneedling, commonly performed as a course of three.",price:"\xa3110 \xb7 course of 3 \xa3295"}],benefits:["Improved texture, hydration and clarity","Brighter, more even-looking skin","Treatments matched to your skin on the day","Easy to combine with a long-term plan"]},{slug:"microneedling",cat:"skin-rejuvenation-facials",title:"Microneedling",img:"/img/t-micro.jpg",desc:"Precision SkinPen microneedling to support skin renewal, healthy ageing, texture, scarring and overall skin quality.",topics:["SkinPen Precision Elite","SkinPen + Medik8 PDRN","Indications","Treatment courses","What to expect","Aftercare"],intro:["Microneedling creates controlled micro-channels in the skin to trigger collagen and elastin production. This natural repair process helps soften acne scars, refine pores, smooth skin texture and improve overall skin quality.","SkinPen is an FDA-cleared device designed to deliver precise, consistent collagen stimulation with minimal trauma to the skin."],items:[{name:"SkinPen Precision Elite",desc:"Precise, consistent microneedling for renewal, texture and scarring.",price:"From \xa3225"},{name:"SkinPen + Medik8 PDRN",desc:"Microneedling combined with Medik8 PDRN to support repair and skin quality."}],benefits:["Acne scarring","Uneven texture","Enlarged pores","Fine lines, dull or tired skin"]},{slug:"skin-regeneration",cat:"regenerative-aesthetics",title:"Skin Regeneration",img:"/img/t-regen.jpg",desc:"Personalised PRP and PRF treatments designed to support skin quality, collagen and natural-looking facial rejuvenation.",topics:["PRP","PRF","Collagen Biofiller","Polynucleotides","Lumi Eyes","Treatment areas","Courses"],intro:["Regenerative treatments work with your body’s own healing processes. A small blood sample is processed to isolate platelet-rich plasma (PRP) or platelet-rich fibrin (PRF), which is then applied or injected to encourage collagen production and support natural repair.","The result is skin that looks fresher and healthier, with natural-looking improvement that builds over time."],items:[{name:"PRP Skin Rejuvenation",desc:"Uses your own growth factors to stimulate skin regeneration from within.",price:"From \xa3167"},{name:"PRP Bio-Gel (collagen biofiller)",desc:"Platelet-rich plasma converted into a soft, natural gel to restore subtle volume while delivering regenerative benefits.",price:"From \xa3225"},{name:"Polynucleotides – Vitaran\xae",desc:"Purified DNA fragments that support skin repair, elasticity and hydration.",price:"1 area \xa3167 \xb7 2 areas \xa3225 \xb7 3 areas \xa3320"},{name:"Lumi Eyes\xae",desc:"A specialised polynucleotide treatment for the delicate under-eye area.",price:"From \xa3140"}],benefits:["Texture improvement","Fine lines","Dull or tired skin","Overall skin vitality"]},{slug:"hair-regeneration",cat:"regenerative-aesthetics",title:"Hair Regeneration",img:"/img/t-hair.jpg",desc:"Personalised PRP and PRF programmes designed to support scalp health and concerns around thinning hair.",topics:["Hair / scalp assessment","PRP","PRF","Recommended courses","Maintenance","Suitability"],intro:["Hair and scalp concerns deserve the same careful assessment as skin. Your programme begins with a hair and scalp assessment to understand your concerns and whether regenerative treatment is suitable for you.","Personalised PRP and PRF programmes are then planned as a course, with maintenance as needed."],items:[{name:"Hair & scalp assessment",desc:"A consultation to understand your concerns, history and suitability."},{name:"PRP / PRF hair programmes",desc:"Regenerative treatment courses designed to support scalp health and thinning hair, with maintenance where appropriate."}],benefits:["Supports scalp health","Personalised course length","Clear guidance on suitability and maintenance"]},{slug:"facial-balancing",cat:"facial-balancing-aesthetic-refinement",title:"Facial Balancing",img:"/img/t-balance.jpg",desc:"A whole-face approach considering proportion, profile and balance before individual features.",topics:["Facial assessment","Profile balancing","Cheeks","Chin","Jawline","Personalised treatment planning"],intro:["We don’t treat features in isolation. A whole-face approach considers proportion, profile and balance first, so each treatment fits the bigger picture.","Jawline and cheek treatments use carefully placed dermal filler to restore structure and definition, creating balanced, natural facial contours."],items:[{name:"Facial assessment & planning",desc:"Profile and proportion assessment, followed by a personalised plan."},{name:"Jawline & cheek contouring",desc:"Restores structure and definition in key areas of facial support.",price:"From \xa3300"}],benefits:["Facial definition","Cheek structure","Balanced, natural-looking contours"]},{slug:"natural-enhancement",cat:"facial-balancing-aesthetic-refinement",title:"Natural Enhancement",img:"/img/c-refine.jpg",desc:"Subtle, considered aesthetic treatments designed to refine rather than redefine.",topics:["Dermal fillers","Lip enhancement","Facial contouring","Natural-looking enhancement","Consultation for lines and facial concerns"],intro:["Subtle injectable treatments designed to soften lines, restore balance and refresh natural facial harmony — never overdone.","Every treatment begins with a consultation, so we can recommend only what is right for you."],items:[{name:"Anti-wrinkle treatments",desc:"Gently relax overactive muscles that cause expression lines, softening existing lines while keeping natural movement.",price:"From \xa3180"},{name:"Dermal fillers",desc:"Restore lost volume and refine contours while keeping natural balance.",price:"From \xa3250"},{name:"Lip enhancement",desc:"Refines lip shape, symmetry and hydration for soft, balanced lips.",price:"From \xa3250"},{name:"Skin boosters – Profhilo\xae / Jalupro\xae",desc:"Hydrating treatments that improve elasticity and skin quality without changing facial structure.",price:"From \xa3250"}],benefits:["Forehead, frown and crow’s feet lines","Mid-face support and softened folds","Lip border definition and symmetry","Hydration and elasticity"]},{slug:"face-beard-laser",cat:"laser-hair-removal",title:"Face & Beard",img:"/img/t-beard.jpg",desc:"Precision laser hair reduction for the face, neck and cleaner beard-line definition.",topics:["Upper lip","Chin","Under-chin","Front of neck","Beard-line shaping","Consultation","Patch test","Courses"],intro:["Personalised laser hair-reduction programmes for the face and neck, including precise beard-line definition.","Every programme begins with a consultation and a patch test, and is planned as a course tailored to your skin and hair profile."],items:[{name:"Face",desc:"Upper lip, chin and other facial areas."},{name:"Neck & beard-line",desc:"Under-chin, front of neck and beard-line shaping for a cleaner finish."}],benefits:["Long-term hair reduction","Cleaner, sharper lines","Patch test before treatment"]},{slug:"body-laser",cat:"laser-hair-removal",title:"Body",img:"/img/t-body.jpg",desc:"Personalised laser hair reduction for individual body areas or combination treatment courses.",topics:["Underarms","Bikini","Arms","Abdomen","Back","Legs","Combination packages","Consultation and patch test"],intro:["Long-term hair reduction for the body, tailored to your individual skin and hair profile.","Choose individual areas or combination courses. A consultation and a complimentary test patch come first."],items:[{name:"Individual areas",desc:"Underarms, bikini, arms, abdomen, back and legs."},{name:"Combination packages",desc:"Courses combining several areas for convenience."}],benefits:["Smooth skin over time","Personalised course plan","Complimentary test patch"]},{slug:"inside-out-skin-health",cat:"skin-health-wellness",title:"Inside-Out Skin Health",img:"/img/t-inside.jpg",desc:"Professional skincare and targeted nutritional support working together to support healthier-looking skin from the inside out.",topics:["Advanced Nutrition Programme","Medik8","Environ","IS Clinical","Pigmentation support","Acne / congestion","Personalised homecare"],intro:["Skin health is influenced by internal factors including nutrition, gut health and the skin microbiome. We combine professional skincare with targeted nutritional support to work on your skin from both sides."],items:[{name:"Professional skincare",desc:"Science-led skincare from Medik8, Environ and IS Clinical, chosen around your skin and goals."},{name:"Internal skin support",desc:"Targeted nutraceutical support, including the Advanced Nutrition Programme, to support collagen production and skin vitality from within."}],benefits:["Supports skin health from within","Strengthens the skin barrier","Maintains treatment results","Personalised homecare plan"]},{slug:"cancer-care-skin-support",cat:"skin-health-wellness",title:"Cancer Care Skin Support",img:"/img/t-cancer.jpg",desc:"Gentle, considered skincare and supportive treatments for skin affected during or following cancer treatment.",topics:["Harmony Facial","Sensitive / compromised-skin support","Appropriate professional skincare","Homecare","Consultation and individual suitability"],intro:["Gentle, considered care for skin affected during or following cancer treatment, and a quiet space to simply switch off.","Every client begins with a consultation to establish individual suitability, and we work alongside your wider care."],items:[{name:"Harmony Facial",desc:"A gentle, relaxing facial designed for sensitive and compromised skin."},{name:"Skin support & homecare",desc:"Appropriate professional skincare and homecare for skin affected by treatment."},{name:"Gentle wellness massage",desc:"Relaxing, restorative time for wellbeing."}],benefits:["Gentle care for sensitive skin","Individual suitability check first","Calm, unhurried appointments"]}],o=[{name:"Sarah M.",treatment:"PRP",text:"I was honestly so nervous about PRP \uD83D\uDE02 Nearly cancelled! It was absolutely fine though. I've had a few people ask what I've done to my skin which says it all really. It's just looking fresher. Really happy with it."},{name:"Emma T.",treatment:"Harmony Facial",text:"Loved this. So relaxing and my skin felt amazing afterwards. Even a few days later it still felt really soft. Will definitely have this one again."},{name:"Aisha K.",treatment:"Skin Consultation",text:"Finally somebody actually explained my skin to me! I've got a drawer full of products I've bought and hardly used. I've stripped everything right back now and can already see a difference. Wish I'd done this ages ago."},{name:"Rebecca T.",treatment:"Microneedling + LED",text:"Wasn't looking forward to the microneedling if I'm honest \uD83D\uDE02 but it really wasn't as bad as I'd built it up to be. I was talked through everything and kept checking I was OK. Skin is already feeling smoother. Booked again."},{name:"Janet R.",treatment:"Cancer Care & Wellness",text:"I can't really explain this one. I've spent months being a patient and having people doing things to me. This didn't feel like that. I could just lie there, switch off and be Janet for a bit. That meant a lot."},{name:"David H.",treatment:"Wellbeing for Carers",text:"My wife actually booked this for me because apparently I'm terrible at looking after myself! She's probably right. I didn't think it would be my sort of thing but I really enjoyed it. Properly switched off for once."}],l=[{t:"Skin Quality & Ageing",d:"Fine lines, texture, hydration, loss of firmness and overall skin quality.",img:"/img/c-ageing.jpg",to:"skin-rejuvenation-facials"},{t:"Pigmentation & Uneven Tone",d:"Personalised approaches to pigmentation, sun damage and uneven-looking skin tone.",img:"/img/c-pigment.jpg",to:"skin-rejuvenation-facials"},{t:"Acne, Congestion & Texture",d:"Supporting clearer skin, visible pores, congestion, post-acne marks and uneven texture.",img:"/img/c-acne.jpg",to:"skin-rejuvenation-facials"},{t:"Skin Regeneration & Renewal",d:"Supporting collagen, skin quality and renewal through regenerative and collagen-stimulating approaches.",img:"/img/c-regen.jpg",to:"regenerative-aesthetics"},{t:"Hair & Scalp",d:"Personalised approaches to hair and scalp concerns, including regenerative treatment programmes.",img:"/img/c-hair.jpg",to:"regenerative-aesthetics"},{t:"Unwanted Hair",d:"Long-term hair reduction for the face and body, tailored to your individual skin and hair profile.",img:"/img/c-unwanted.jpg",to:"laser-hair-removal"},{t:"Aesthetic Refinement",d:"Clinically guided aesthetic treatments designed to enhance natural features — refine rather than redefine.",img:"/img/c-refine.jpg",to:"facial-balancing-aesthetic-refinement"},{t:"Skin Health & Maintenance",d:"Professional skincare, facials and ongoing treatment plans designed to protect and maintain your results.",img:"/img/c-health.jpg",to:"skin-health-wellness"}],c=[{slug:"facial-treatments",t:"Facial Treatments",d:"Understand how professional facials work, what they can and cannot do, and how to choose the right one for your skin.",img:"/img/journal-1.jpg"},{slug:"skin-tips",t:"Skin Tips",d:"Confused by skin tips, ingredient advice and social media trends? Clear, clinically-led guidance for everyday skin health.",img:"/img/journal-2.jpg"},{slug:"skin-treatments",t:"Skin Treatments",d:"Explore advanced skin treatments for pigmentation, texture, ageing and hydration, and what to expect from each.",img:"/img/journal-3.jpg"}]}}]);